import type { Dialogue, Exercise, Lesson, Phrase, Question, SpeakingTask } from './types';

const pairs = (text: string): Phrase[] => text.split('\n').map(l => { const [en, tr] = l.split('|'); return { en, tr }; });
const dialogue = (title: string, gist: string, text: string): Dialogue => ({ title, gist, lines: pairs(text).map((p, i) => ({ speaker: i % 2 ? 'Mia' : 'Alex', ...p })) });
const q = (dialogue: number, type: Question['type'], prompt: string, options: string[], answer: number, evidence: string, explanation: string, reviewPhrase = 0): Question => ({ dialogue, type, prompt, options, answer, evidence, explanation, reviewPhrase });
const ex = (type: Exercise['type'], prompt: string, answer: string, hint: string, explanation: string): Exercise => ({ type, prompt, answer, hint, explanation });
const task = (prompt: string, scaffold: string, success: string): SpeakingTask => ({ prompt, scaffold, success });
type Seed = { week: number; day: number; title: string; subtitle: string; goal: string; phrases: string; vocabulary: string; dialogues: Dialogue[]; questions: Question[]; exercises: Exercise[]; speaking: SpeakingTask[]; homework: string; count: string; grammar: string; bonus: string[] };
